import React, { useState, useEffect } from 'react';
import axiosInstance from 'axios';

export default function TeacherQuiz({ userName, subject, qualifications, teacherGrades, timetable }) {
  
  const [quizzes, setQuizzes] = useState([]);
  const [masterBank, setMasterBank] = useState([]);

  const [selectedQuizId, setSelectedQuizId] = useState('');
  const [quizTitle, setQuizTitle] = useState('');

  // ඩේටාබේස් තොරතුරු ලබාගැනීමේ States
  const [dbTeachers, setDbTeachers] = useState([
    { id: 1, teacher_code: 'TC_001', full_name: 'Charaka Dikwella' },
    { id: 2, teacher_code: 'TC_002', full_name: 'Buddhika Darshani' },
    { id: 3, teacher_code: 'TC_003', full_name: 'Ravindu Jayaweera' }
  ]);

  const [dbSubjects, setDbSubjects] = useState([
    { id: 1, subject_code: 'Sub_001', subject_name: 'Mathematics' },
    { id: 2, subject_code: 'Sub_002', subject_name: 'Science' },
    { id: 5, subject_code: 'Sub_005', subject_name: 'ICT' }
  ]);

  const [dbTimetable, setDbTimetable] = useState([
    { id: 1, grade: 'Grade 9', subject: 'Mathematics', teacher: 'Charaka Dikwella' },
    { id: 2, grade: 'Grade 10', subject: 'Mathematics', teacher: 'Charaka Dikwella' },
    { id: 4, grade: 'Grade 6', subject: 'Mathematics', teacher: 'Buddhika Darshani' }, 
    { id: 5, grade: 'Grade 7', subject: 'Mathematics', teacher: 'Buddhika Darshani' }, 
    { id: 6, grade: 'Grade 8', subject: 'Mathematics', teacher: 'Buddhika Darshani' }, 
    { id: 7, grade: 'Grade 6', subject: 'Science', teacher: 'Ravindu Jayaweera' }
  ]);

  const [activeSubject, setActiveSubject] = useState('');

  // 🟢 QUESTION BANK REPOSITORY FILTERS
  const [bankFilterGrade, setBankBankFilterGrade] = useState('Grade 8');
  const [bankFilterSubject, setBankFilterSubject] = useState('Mathematics');

  // Form States for Questions
  const [editingId, setEditingId] = useState(null);
  const [qText, setQText] = useState('');
  const [optA, setOptA] = useState('');
  const [optB, setOptB] = useState('');
  const [optC, setOptC] = useState('');
  const [optD, setOptD] = useState('');
  const [correctOpt, setCorrectOpt] = useState('A');
  const [qMarks, setQMarks] = useState(2);

  const refreshData = () => {
    axiosInstance.get('http://localhost:8082/api/quizzes')
      .then(res => setQuizzes(Array.isArray(res.data) ? res.data : []))
      .catch(err => console.log("Quizzes Fetch Error:", err));
    
    axiosInstance.get('http://localhost:8082/api/question-bank')
      .then(res => setMasterBank(Array.isArray(res.data) ? res.data : []))
      .catch(err => console.log("Question Bank Fetch Error:", err));

    axiosInstance.get('http://localhost:8082/api/view-subjects').then(res => setDbSubjects(res.data)).catch(() => {});
    axiosInstance.get('http://localhost:8082/api/timetable').then(res => setDbTimetable(res.data)).catch(() => {});
  };

  useEffect(() => { 
    refreshData(); 
  }, []);

  // ටීචර්ගේ දත්ත ෆිල්ටර් කිරිමේ රීති
  const myTimeSlots = dbTimetable.filter(t => t.teacher === userName);
  const myUniqueSubjects = [...new Set(myTimeSlots.map(t => t.subject))];
  const availableGrades = [...new Set(myTimeSlots.filter(t => t.subject === (activeSubject || 'Mathematics')).map(t => t.grade))];

  const [formPaperGrade, setFormPaperGrade] = useState('Grade 8');

  useEffect(() => {
    if (availableGrades.length > 0) setFormPaperGrade(availableGrades[0]);
  }, [dbTimetable, activeSubject]);

  useEffect(() => {
    if (myUniqueSubjects.length > 0 && !activeSubject) {
      setActiveSubject(myUniqueSubjects[0]);
      setBankFilterSubject(myUniqueSubjects[0]);
    }
  }, [dbTimetable]);

  const activeQuizDetails = quizzes.find(qz => qz.id === parseInt(selectedQuizId));
  const isCurrentQuizEnabled = activeQuizDetails?.is_enabled === 1 || activeQuizDetails?.is_enabled === true;

  // 1. New Paper Title සාදා ඩේටාබේස් එකට යැවීම
  const handleCreatePaper = (e) => {
    e.preventDefault();
    const payload = { title: quizTitle, grade: formPaperGrade, subject: activeSubject || 'Mathematics', teacher_name: userName, is_enabled: 0 };
    axiosInstance.post('http://localhost:8082/api/add-quiz', payload).then(() => {
      alert(`✅ Quiz Paper "${quizTitle}" සාර්ථකව නිර්මාණය කරන ලදි!`);
      refreshData();
      setQuizTitle('');
    });
  };

  // 2. ප්‍රශ්න පත්‍රයක් සක්‍රීය (Enable) / අක්‍රීය (Disable) කිරීමේ ක්‍රියාවලිය
  const handleToggleEnable = (quiz) => {
    const updatedStatus = quiz.is_enabled === 1 || quiz.is_enabled === true ? 0 : 1;
    axiosInstance.put(`http://localhost:8082/api/toggle-quiz/${quiz.id}`, { ...quiz, is_enabled: updatedStatus })
      .then(() => {
        alert(`💡 Quiz Paper එක සාර්ථකව ${updatedStatus ? '🟢 Enabled' : '🔴 Disabled'} කරන ලදි!`);
        refreshData();
      });
  };

  // 3. ප්‍රශ්න බැංකුවට අලුත්ම ප්‍රශ්නයක් ඇතුළත් කිරීම හෝ පවතින ප්‍රශ්නයක් සංස්කරණය කිරීම
  const handleSaveQuestion = (e) => {
    e.preventDefault();
    
    // 🔒 GUARD CLAUSE: පේපර් එකක් තෝරා ඇතිවිට එය සක්‍රීය නම් සංස්කරණය කිරීම වළක්වයි
    if (selectedQuizId && isCurrentQuizEnabled) {
      alert("⚠️ මෙම ප්‍රශ්න පත්‍රය දැනට සක්‍රීය (Enabled) තත්වයේ පවතී. වෙනස්කම් කිරීමට ප්‍රථම කරුණාකර එය අක්‍රීය (Disabled) කරන්න!");
      return;
    }

    const payload = {
      quiz_id: selectedQuizId ? parseInt(selectedQuizId) : 0, 
      question_text: qText, marks: parseInt(qMarks),
      option_a: optA, option_b: optB, option_c: optC, option_d: optD, correct_option: correctOpt
    };

    if (editingId) {
      axiosInstance.put(`http://localhost:8082/api/edit-question/${editingId}`, payload)
        .then(() => {
          alert("✅ ප්‍රශ්නය සාර්ථකව යාවත්කාලීන (Updated) කරන ලදි!");
          setEditingId(null); clearForm(); refreshData();
        });
    } else {
      axiosInstance.post('http://localhost:8082/api/add-question', payload)
        .then(() => {
          alert("✅ ප්‍රශ්නය සාර්ථකව පද්ධතියට ඇතුළත් කරන ලදි!");
          clearForm(); refreshData();
        });
    }
  };

  // 4. ප්‍රශ්න බැංකුවේ ඇති ප්‍රශ්නයක් පේපර් එකට සම්බන්ධ කිරීම (Link)
  const handleQuickLink = (question) => {
    if (!selectedQuizId) { alert("⚠️ කරුණාකර මුලින්ම Step 2 එකෙන් පේපර් එකක් තෝරන්න!"); return; }
    if (isCurrentQuizEnabled) { alert("⚠️ පේපර් එක සක්‍රීය (Enabled) බැවින් ප්‍රශ්න ඇතුළත් කළ නොහැක!"); return; }

    const payload = { ...question, quiz_id: parseInt(selectedQuizId) };
    axiosInstance.put(`http://localhost:8082/api/edit-question/${question.id}`, payload)
      .then(() => {
        alert("➕ ප්‍රශ්නය සාර්ථකව පේපර් එකට ලින්ක් කරන ලදි!");
        refreshData();
      });
  };

  // 5. ප්‍රශ්නයක් ඩේටාබේස් එකෙන් සහමුලින්ම මකා දැමීම
  const handleDeleteQuestion = (id) => {
    if (selectedQuizId && isCurrentQuizEnabled) {
      alert("⚠️ පේපර් එක සක්‍රීය (Enabled) බැවින් ප්‍රශ්න මකා දැමිය නොහැක!");
      return;
    }
    if (window.confirm("මෙම ප්‍රශ්නය පද්ධතියෙන් සහමුලින්ම මකා දැමීමට අවශ්‍යද?")) {
      axiosInstance.delete(`http://localhost:8082/api/delete-question/${id}`).then(() => {
        alert("🗑️ Question removed permanently!");
        refreshData();
      });
    }
  };

  // 6. පේපර් එකෙන් අයින් කර නැවත බැංකුවටම දැමීම (Unlink)
  const handleUnlinkQuestion = (question) => {
    if (isCurrentQuizEnabled) {
      alert("⚠️ පේපර් එක සක්‍රීය (Enabled) බැවින් ප්‍රශ්න ඉවත් කළ නොහැක!");
      return;
    }
    const payload = { ...question, quiz_id: 0 };
    axiosInstance.put(`http://localhost:8082/api/edit-question/${question.id}`, payload).then(() => refreshData());
  };

  const clearForm = () => { setQText(''); setOptA(''); setOptB(''); setOptC(''); setOptD(''); setCorrectOpt('A'); setEditingId(null); };
  const handleStartEdit = (q) => { 
    if (selectedQuizId && isCurrentQuizEnabled) {
      alert("⚠️ පේපර් එක සක්‍රීය (Enabled) බැවින් සංස්කරණය කළ නොහැක!");
      return;
    }
    setEditingId(q.id); setQText(q.question_text); setOptA(q.option_a); setOptB(q.option_b); setOptC(q.option_c); setOptD(q.option_d); setCorrectOpt(q.correct_option); setQMarks(q.marks); 
  };

  // 🟢 FILTER ARCHITECTURES
  const filteredQuizzes = quizzes.filter(q => q.subject_name === (activeSubject || 'Mathematics'));
  
  // 1. පේපර් එකට දැනට එකතු කර ඇති ප්‍රශ්න ලිස්ට් එක (Sub-questions View)
  const activePaperQuestions = masterBank.filter(q => q.quiz_id === parseInt(selectedQuizId));
  
  // 2. ප්‍රශ්න බැංකුවේ ඇති unassigned ප්‍රශ්න Grade සහ Subject අනුව filter කිරීම
  const filteredBankQuestions = masterBank.filter(q => 
    q.quiz_id === 0 && 
    (q.grade === bankFilterGrade || !q.grade) && 
    (q.subject === bankFilterSubject || !q.subject || q.subject === 'Mathematics')
  );

  return (
    <div style={{ animation: 'fadeIn 0.5s', fontFamily: 'sans-serif', display: 'flex', flexDirection: 'column', gap: '25px' }}>
      
      {/* TOP GLOBAL SUBJECT DROPDOWN */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', backgroundColor: '#f8fafc', padding: '12px 20px', borderRadius: '12px', border: '1px solid #cbd5e1' }}>
        <div><h2 style={{ color: '#1e293b', margin: 0, fontSize: '18px' }}>📝 MCQ Exam Dashboard Management</h2></div>
        <div style={{ display: 'flex', alignItems: 'center', gap: '10px' }}>
          <span style={{ fontSize: '13px', fontWeight: 'bold', color: '#475569' }}>Active Subject:</span>
          <select value={activeSubject} onChange={e => { setActiveSubject(e.target.value); setBankFilterSubject(e.target.value); setSelectedQuizId(''); }} style={{ padding: '8px 14px', borderRadius: '8px', border: '1px solid #cbd5e1', fontWeight: 'bold', fontSize: '13px', outline: 'none' }}>
            {myUniqueSubjects.map(subName => <option key={subName} value={subName}>{subName}</option>)}
            {myUniqueSubjects.length === 0 && <option value="Mathematics">Mathematics</option>}
          </select>
        </div>
      </div>

      {/* STEP 1 & 2 TOP CONTROL GRID */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px' }}>
        <div style={styles.card('#15803d')}>
          <h4 style={styles.stepTitle('#15803d')}>Step 1: Create a New Quiz Paper</h4>
          <form onSubmit={handleCreatePaper} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <input type="text" placeholder="e.g., 2 වාර මැද ඇගයීම" value={quizTitle} onChange={e => setQuizTitle(e.target.value)} required style={styles.fullInput} />
            <select value={formPaperGrade} onChange={e => setFormPaperGrade(e.target.value)} style={styles.fullInput}>
              {availableGrades.map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <button type="submit" style={{ ...styles.btn, backgroundColor: '#15803d', width: '100%' }}>Create Paper Schema</button>
          </form>
        </div>

        <div style={styles.card('#2563eb')}>
          <h4 style={styles.stepTitle('#2563eb')}>Step 2: Active Exam Paper Target</h4>
          <select value={selectedQuizId} onChange={e => { setSelectedQuizId(e.target.value); clearForm(); }} style={styles.fullInput}>
            <option value="">-- Choose Target Exam Paper --</option>
            {filteredQuizzes.map(q => <option key={q.id} value={q.id}>{q.title} ({q.grade})</option>)}
          </select>
        </div>
      </div>

      {/* MAIN SYSTEM LAYOUT */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.3fr', gap: '25px', alignItems: 'start' }}>
        
        {/* LEFT WORKSPACE: QUESTION WRITER */}
        <div style={styles.card(editingId ? '#ea580c' : '#475569')}>
          <h3 style={{ margin: '0 0 15px 0', fontSize: '15px', color: '#1e293b' }}>
            {editingId ? '✏️ Edit Selected MCQ Question' : '➕ Add Custom Question to Bank'}
          </h3>
          
          {selectedQuizId && isCurrentQuizEnabled && (
            <div style={{ backgroundColor: '#fee2e2', color: '#b91c1c', padding: '10px', borderRadius: '8px', fontSize: '12px', fontWeight: 'bold', marginBottom: '12px' }}>
              🔒 LOCK ACTIVE: පේපර් එක සක්‍රීය බැවින් නව ප්‍රශ්න ඇතුළත් කිරීම තාවකාලිකව අත්හිටුවා ඇත.
            </div>
          )}

          <form onSubmit={handleSaveQuestion} style={{ display: 'flex', flexDirection: 'column', gap: '12px' }}>
            <div>
              <label style={styles.label}>ප්‍රශ්න විස්තරය</label>
              <textarea placeholder="ගණිත ගැටලුව මෙතන ලියන්න..." value={qText} onChange={e => setQText(e.target.value)} required disabled={selectedQuizId && isCurrentQuizEnabled} style={{ ...styles.fullInput, height: '60px', resize: 'none' }} />
            </div>
            <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'A'} onChange={() => setCorrectOpt('A')} disabled={selectedQuizId && isCurrentQuizEnabled} /><input type="text" placeholder="Option A" value={optA} onChange={e => setOptA(e.target.value)} required disabled={selectedQuizId && isCurrentQuizEnabled} style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'B'} onChange={() => setCorrectOpt('B')} disabled={selectedQuizId && isCurrentQuizEnabled} /><input type="text" placeholder="Option B" value={optB} onChange={e => setOptB(e.target.value)} required disabled={selectedQuizId && isCurrentQuizEnabled} style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'C'} onChange={() => setCorrectOpt('C')} disabled={selectedQuizId && isCurrentQuizEnabled} /><input type="text" placeholder="Option C" value={optC} onChange={e => setOptC(e.target.value)} required disabled={selectedQuizId && isCurrentQuizEnabled} style={styles.fullInput} /></div>
              <div style={styles.optRow}><input type="radio" checked={correctOpt === 'D'} onChange={() => setCorrectOpt('D')} disabled={selectedQuizId && isCurrentQuizEnabled} /><input type="text" placeholder="Option D" value={optD} onChange={e => setOptD(e.target.value)} required disabled={selectedQuizId && isCurrentQuizEnabled} style={styles.fullInput} /></div>
            </div>
            <div style={{ display: 'flex', gap: '10px' }}>
              <button type="submit" disabled={selectedQuizId && isCurrentQuizEnabled} style={{ ...styles.btn, backgroundColor: editingId ? '#ea580c' : '#475569', flex: 1, padding: '11px' }}>
                {editingId ? 'Update Matrix 💾' : 'Save Inside Bank 💾'}
              </button>
              {editingId && <button type="button" onClick={clearForm} style={{ ...styles.btn, backgroundColor: '#cbd5e1', color: '#334155' }}>Cancel</button>}
            </div>
          </form>
        </div>

        {/* RIGHT WORKSPACE: DYNAMIC QUESTION REPOSITORY POOL */}
        <div style={styles.card('#6b21a8')}>
          <h3 style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#1e293b' }}>📚 Central Question Bank Repository</h3>
          <p style={{ margin: '0 0 15px 0', fontSize: '12px', color: '#64748b' }}>පල්ලෙහා Drops මගින් ඕනෑම ශ්‍රේණියක ප්‍රශ්න තෝරාගෙන පේපර් එකට සම්බන්ධ කරන්න.</p>
          
          {/* 🟢 SEPARATE FILTERS FOR BANK REPOSITORY */}
          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '10px', marginBottom: '15px' }}>
            <select value={bankFilterGrade} onChange={e => setBankBankFilterGrade(e.target.value)} style={styles.fullInput}>
              {['Grade 6', 'Grade 7', 'Grade 8', 'Grade 9', 'Grade 10'].map(g => <option key={g} value={g}>{g}</option>)}
            </select>
            <select value={bankFilterSubject} onChange={e => setBankFilterSubject(e.target.value)} style={styles.fullInput}>
              {myUniqueSubjects.map(s => <option key={s} value={s}>{s}</option>)}
              {myUniqueSubjects.length === 0 && <option value="Mathematics">Mathematics</option>}
            </select>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '12px', maxHeight: '250px', overflowY: 'auto' }}>
            {filteredBankQuestions.length > 0 ? (
              filteredBankQuestions.map((q, idx) => (
                <div key={q.id || idx} style={{ backgroundColor: '#f8fafc', padding: '15px', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
                  <h5 style={{ margin: '0 0 10px 0', fontSize: '13.5px', lineHeight: '1.4', color: '#1e293b' }}>{q.question_text}</h5>
                  <div style={{ display: 'flex', gap: '8px' }}>
                    <button onClick={() => handleStartEdit(q)} style={styles.miniBtn}>✏️ Edit</button>
                    <button onClick={() => handleDeleteQuestion(q.id)} style={{ ...styles.miniBtn, color: '#b91c1c', backgroundColor: '#fee2e2' }}>🗑️ Delete</button>
                    <button 
                      onClick={() => handleQuickLink(q)} 
                      disabled={!selectedQuizId || isCurrentQuizEnabled}
                      style={{ 
                        ...styles.miniBtn, marginLeft: 'auto',
                        backgroundColor: (!selectedQuizId || isCurrentQuizEnabled) ? '#cbd5e1' : '#16a34a', color: 'white', border: 'none' 
                      }}
                    >
                      ➕ Link to Active Paper
                    </button>
                  </div>
                </div>
              ))
            ) : (
              <p style={{ color: '#94a3b8', textAlign: 'center', fontSize: '13px', fontStyle: 'italic', padding: '15px' }}>
                📭 මෙම සර්ච් ෆිල්ටර් එකට අදාළ ප්‍රශ්න කිසිවක් බැංකුවේ දැනට සොයාගත නොහැක.
              </p>
            )}
          </div>
        </div>

      </div>

      {/* BOTTOM WORKSPACE: CREATED PAPERS & LIVE BLUEPRINT INSPECTOR */}
      <div style={{ display: 'grid', gridTemplateColumns: '1fr 1.3fr', gap: '25px', marginTop: '5px' }}>
        
        {/* LEFT BOTTOM: CREATED PAPERS LIST */}
        <div style={styles.card('#e11d48')}>
          <h3 style={{ margin: '0 0 5px 0', fontSize: '16px', color: '#1e293b' }}>📂 Created Quiz Papers & Visibility Control</h3>
          <p style={{ margin: '0 0 15px 0', fontSize: '12px', color: '#64748b' }}>ප්‍රශ්න පත්‍රවල දෘශ්‍යතාව මෙතැනින් පාලනය කරන්න.</p>
          <div style={{ display: 'flex', flexDirection: 'column', gap: '10px', maxHeight: '350px', overflowY: 'auto' }}>
            {filteredQuizzes.length > 0 ? (
              filteredQuizzes.map((qz, idx) => {
                const activeStatus = isEnabled(qz);
                return (
                  <div key={qz.id || idx} style={{ backgroundColor: '#f8fafc', padding: '12px', borderRadius: '10px', border: '1px solid #e2e8f0', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div>
                      <h5 style={{ margin: '0 0 4px 0', fontSize: '13.5px', color: '#1e293b', fontWeight: '600' }}>{qz.title}</h5>
                      <span style={{ fontSize: '11px', backgroundColor: '#e2e8f0', padding: '2px 6px', borderRadius: '4px', fontWeight: 'bold', color: '#475569' }}>{qz.grade}</span>
                    </div>
                    <button 
                      onClick={() => handleToggleEnable(qz)} 
                      style={{ padding: '6px 14px', borderRadius: '8px', border: 'none', cursor: 'pointer', fontWeight: 'bold', fontSize: '11.5px', backgroundColor: activeStatus ? '#16a34a' : '#dc2626', color: 'white' }}
                    >
                      {activeStatus ? '🟢 Enabled' : '🔴 Disabled'}
                    </button>
                  </div>
                );
              })
            ) : (
              <p style={{ color: '#94a3b8', textAlign: 'center', fontSize: '13px', fontStyle: 'italic', padding: '10px' }}>📭 ප්‍රශ්න පත්‍ර කිසිවක් සාදා නැත.</p>
            )}
          </div>
        </div>

        {/* 🟢 RIGHT BOTTOM: SUB-QUESTIONS INSPECTOR & ASSESSMENT SHEET */}
        <div style={{ backgroundColor: 'white', padding: '30px', borderRadius: '16px', border: '1px solid #cbd5e1', boxShadow: '0 4px 20px rgba(0,0,0,0.01)' }}>
          <div style={{ borderBottom: '3px double #334155', paddingBottom: '15px', marginBottom: '20px', textAlign: 'center' }}>
            <h3 style={{ margin: '0 0 5px 0', fontSize: '18px', color: '#1e293b' }}>
              {selectedQuizId && activeQuizDetails ? activeQuizDetails.title : "Active Examination Blueprint Sheet"}
            </h3>
            <div style={{ display: 'flex', justifyContent: 'center', gap: '20px', fontSize: '12px', color: '#64748b', fontWeight: '500' }}>
              <span>Subject: {activeSubject}</span>
              <span>Total Sub-Questions: {activePaperQuestions.length}</span>
              <span style={{ color: isCurrentQuizEnabled ? '#16a34a' : '#dc2626', fontWeight: 'bold' }}>
                Status: {isCurrentQuizEnabled ? '🟢 LIVE (Locked)' : '🔴 EDITABLE (Unlocked)'}
              </span>
            </div>
          </div>

          <div style={{ display: 'flex', flexDirection: 'column', gap: '20px' }}>
            {activePaperQuestions.length > 0 ? (
              activePaperQuestions.map((q, idx) => (
                <div key={q.id || idx} style={{ borderBottom: '1px dashed #cbd5e1', paddingBottom: '15px' }}>
                  <div style={{ display: 'flex', gap: '10px', fontSize: '14px', fontWeight: '600', color: '#1e293b' }}>
                    <span>({idx + 1})</span>
                    <p style={{ margin: 0, flex: 1, lineHeight: '1.4' }}>{q.question_text}</p>
                    
                    {/* 🔒 SECURITY RENDER RULE: පේපර් එක Disabled නම් පමණක් Edit/Delete බටන්ස් වැඩ කරයි */}
                    <div style={{ display: 'flex', gap: '5px' }}>
                      <button onClick={() => handleStartEdit(q)} disabled={isCurrentQuizEnabled} style={{ border: 'none', background: 'none', color: isCurrentQuizEnabled ? '#cbd5e1' : '#2563eb', fontSize: '12px', cursor: 'pointer', fontWeight: 'bold' }}>[✏️ Edit]</button>
                      <button onClick={() => handleUnlinkQuestion(q)} disabled={isCurrentQuizEnabled} style={{ border: 'none', background: 'none', color: isCurrentQuizEnabled ? '#cbd5e1' : '#ef4444', fontSize: '12px', cursor: 'pointer', fontWeight: 'bold' }}>[❌ Remove]</button>
                    </div>
                  </div>

                  <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '6px', paddingLeft: '25px', marginTop: '6px', fontSize: '13px', color: '#334155' }}>
                    <div>A) {q.option_a}</div>
                    <div>B) {q.option_b}</div>
                    <div>C) {q.option_c}</div>
                    <div>D) {q.option_d}</div>
                  </div>
                  <div style={{ paddingLeft: '25px', fontSize: '11px', color: '#16a34a', fontWeight: 'bold', marginTop: '5px' }}>
                    🎯 Answer Matrix Key: Option ({q.correct_option})
                  </div>
                </div>
              ))
            ) : (
              <div style={{ textAlign: 'center', padding: '30px', color: '#94a3b8', fontStyle: 'italic', fontSize: '13px' }}>
                📭 මෙම ප්‍රශ්න පත්‍රය දැනට හිස්ව පවතී. ඉහත ප්‍රශ්න බැංකුවෙන් ප්‍රශ්න මෙතැනට සම්බන්ධ කරන්න.
              </div>
            )}
          </div>
        </div>

      </div>

    </div>
  );
}

const styles = {
  card: (color) => ({ backgroundColor: 'white', padding: '24px', borderRadius: '15px', borderTop: `5px solid ${color}`, display: 'flex', flexDirection: 'column', boxShadow: '0 4px 15px rgba(0,0,0,0.01)' }),
  stepTitle: (color) => ({ margin: '0 0 12px 0', fontSize: '14.5px', color: color, fontWeight: 'bold' }),
  fullInput: { width: '100%', padding: '11px', borderRadius: '8px', border: '1px solid #cbd5e1', backgroundColor: '#f8fafc', fontSize: '13.5px', boxSizing: 'border-box', outline: 'none' },
  btn: { color: 'white', border: 'none', padding: '11px 20px', borderRadius: '8px', fontWeight: 'bold', fontSize: '13.5px', cursor: 'pointer' },
  label: { display: 'block', fontSize: '12px', fontWeight: 'bold', color: '#475569', marginBottom: '6px' },
  optRow: { display: 'flex', alignItems: 'center', gap: '10px', width: '100%' },
  miniBtn: { padding: '4px 10px', border: '1px solid #cbd5e1', backgroundColor: 'white', borderRadius: '6px', fontSize: '11.5px', fontWeight: 'bold', color: '#334155', cursor: 'pointer' }
};
